/**
 * Tree-sitter live structure per open file (steal #2 — 2026-11-14).
 *
 * The engine: one Parser per language (typescript + tsx), one live
 * Tree per open file, re-parsed incrementally on every edit. All
 * local, all in-memory, synchronous once initialised — no model, no
 * network, no SP, never blocks the composer. The only limit is the
 * intelligence of the context it feeds (Gary, 2026-11-14: the only
 * bottleneck is ours, or the driving intelligence's).
 *
 * Loading: the WASM binaries are vendored as base64
 * (src/lib/treeSitterWasm.ts, generated by
 * scripts/generate-tree-sitter-assets.mjs) and instantiated from
 * bytes — the packaged app loads from disk (file://) with
 * webSecurity on, and a file:// page cannot fetch a sibling file://
 * URL, so there is no fetch path at all. The generated chunk is
 * dynamic-imported on first use, so the ~4 MB of grammar bytes
 * never touch the startup path. MIT throughout (tree-sitter core +
 * tree-sitter-typescript grammars).
 *
 * Failure mode (Kite's contract): a dead engine returns no
 * structure, never an error in the user's face. Every public
 * function degrades to null/false when the engine is unavailable
 * or a parse throws. Guest: parse in memory, persist nothing —
 * the per-file trees are dropped when the file closes.
 *
 * Incremental parsing, the core steal: parse once, then on each
 * edit apply the edit to the old tree (Tree.edit) and re-parse
 * with the old tree as input — unchanged subtrees are shared, only
 * the edited region is re-parsed. The edit is computed from the
 * old/new text by common prefix/suffix (see computeEdit); when it
 * cannot be computed, the file is fully re-parsed.
 */

import {
  Parser,
  Language,
  Query,
  Edit,
  type Node,
  type QueryMatch,
  type QueryOptions,
  type Tree,
} from 'web-tree-sitter';
import {
  extractDefinitions,
  extractExports,
  extractImports,
  getEnclosingFunction,
  getIdentifiersInScope,
  isTopLevelDefinition,
  monacoPositionToTreeSitter,
  positionToByteOffset,
  type FileDefinition,
  type EnclosingFunction,
} from './fileStructure';

// web-tree-sitter's .d.ts references EmscriptenModule without
// defining it (no @types/emscripten in Lucid). Declare the two
// fields Parser.init actually honours, so tsc can check the
// options object.
declare global {
  interface EmscriptenModule {
    instantiateWasm?: (
      imports: WebAssembly.Imports,
      onSuccess: (
        instance: WebAssembly.Instance,
        module: WebAssembly.Module,
      ) => void,
    ) => void;
    locateFile?: (path: string, scriptDirectory: string) => string;
  }
}

export type TreeSitterLanguageId = 'typescript' | 'tsx';

export interface FileStructure {
  path: string;
  language: TreeSitterLanguageId;
  definitions: FileDefinition[];
  imports: string[];
  exports: string[];
  /** Top-level definition names, in file order. */
  topLevelNames: string[];
  /** True when the tree parsed with errors — structure is still
   *  returned (the parser is robust to broken code), but a
   *  consumer that needs exact structure should treat it as
   *  best-effort. */
  hasError: boolean;
}

interface CachedTree {
  tree: Tree;
  text: string;
  language: TreeSitterLanguageId;
}

const trees = new Map<string, CachedTree>();
let initPromise: Promise<boolean> | null = null;
let engineReady = false;
const parsers = new Map<TreeSitterLanguageId, Parser>();
const languages = new Map<TreeSitterLanguageId, Language>();
const queryCache = new Map<string, Query>();

/** Decode a base64 string to bytes. Pure — unit-tested on its own. */
export function decodeBase64(base64: string): Uint8Array<ArrayBuffer> {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

/** Which grammar parses this path, or null (not a TS/JS file).
 *  The TS grammar parses plain JS (it extends the JS grammar);
 *  the TSX grammar parses JSX/TSX. */
export function getLanguageForPath(
  path: string,
): TreeSitterLanguageId | null {
  const ext = path.split('.').pop()?.toLowerCase();
  if (ext === 'ts' || ext === 'js' || ext === 'mts' || ext === 'cts') {
    return 'typescript';
  }
  if (ext === 'tsx' || ext === 'jsx') return 'tsx';
  return null;
}

/**
 * Initialise the engine once (lazy — first file open or first
 * completion request). Returns true when the core + both grammars
 * are loaded. Safe to call repeatedly; a failed init is retried
 * on the next call (initPromise is cleared on failure).
 */
export async function ensureTreeSitter(): Promise<boolean> {
  if (engineReady) return true;
  if (!initPromise) {
    initPromise = (async () => {
      try {
        const wasm = await import('./treeSitterWasm');
        const coreBytes = decodeBase64(wasm.TREE_SITTER_CORE_WASM_BASE64);
        await Parser.init({
          instantiateWasm(imports, onSuccess) {
            void WebAssembly.instantiate(coreBytes, imports).then(
              ({ instance, module }) => onSuccess(instance, module),
            );
          },
        });
        const tsBytes = decodeBase64(
          wasm.TREE_SITTER_TYPESCRIPT_WASM_BASE64,
        );
        const tsxBytes = decodeBase64(wasm.TREE_SITTER_TSX_WASM_BASE64);
        const tsLang = await Language.load(tsBytes);
        const tsxLang = await Language.load(tsxBytes);
        languages.set('typescript', tsLang);
        languages.set('tsx', tsxLang);
        for (const [id, lang] of languages) {
          const parser = new Parser();
          parser.setLanguage(lang);
          parsers.set(id, parser);
        }
        engineReady = true;
        return true;
      } catch {
        // Dead engine: no structure, never an error. Clear the
        // promise so a later call retries (e.g. after a reload).
        initPromise = null;
        return false;
      }
    })();
  }
  return initPromise;
}

/** True once the engine has initialised successfully. */
export function isTreeSitterReady(): boolean {
  return engineReady;
}

/**
 * Compute the tree-sitter edit between two versions of a file's
 * text, from the common prefix/suffix. Returns null when the texts
 * are identical (no edit) or when the change cannot be expressed
 * as one contiguous edit (it always can be — prefix/suffix gives
 * the minimal single span — but a surrogate pair split at the
 * boundary is adjusted back so the edit never cuts a code point
 * in half).
 */
export function computeEdit(
  oldText: string,
  newText: string,
): Edit | null {
  if (oldText === newText) return null;
  let prefix = 0;
  const minLen = Math.min(oldText.length, newText.length);
  while (prefix < minLen && oldText[prefix] === newText[prefix]) {
    prefix++;
  }
  let suffix = 0;
  while (
    suffix < minLen - prefix &&
    oldText[oldText.length - 1 - suffix] ===
      newText[newText.length - 1 - suffix]
  ) {
    suffix++;
  }
  // Never split a surrogate pair at the prefix boundary.
  if (
    prefix > 0 &&
    prefix < oldText.length &&
    isHighSurrogate(oldText.charCodeAt(prefix - 1)) &&
    isLowSurrogate(oldText.charCodeAt(prefix))
  ) {
    prefix--;
  }
  const oldEnd = oldText.length - suffix;
  const newEnd = newText.length - suffix;
  const encoder = new TextEncoder();
  const byteOffset = (text: string, index: number) =>
    encoder.encode(text.slice(0, index)).length;
  const startPosition = positionOf(oldText, prefix);
  // Edit is a class in web-tree-sitter 0.27, not a plain object —
  // construct it (the constructor takes the same six fields).
  return new Edit({
    startIndex: byteOffset(oldText, prefix),
    oldEndIndex: byteOffset(oldText, oldEnd),
    newEndIndex: byteOffset(newText, newEnd),
    startPosition,
    oldEndPosition: positionOf(oldText, oldEnd),
    newEndPosition: positionOf(newText, newEnd),
  });
}

function isHighSurrogate(code: number): boolean {
  return code >= 0xd800 && code <= 0xdbff;
}

function isLowSurrogate(code: number): boolean {
  return code >= 0xdc00 && code <= 0xdfff;
}

/** (row, byte column) of the UTF-16 index in the text. */
function positionOf(
  text: string,
  index: number,
): { row: number; column: number } {
  let row = 0;
  let lineStart = 0;
  for (let i = 0; i < index && i < text.length; i++) {
    if (text[i] === '\n') {
      row++;
      lineStart = i + 1;
    }
  }
  const encoder = new TextEncoder();
  return {
    row,
    column: encoder.encode(text.slice(lineStart, index)).length,
  };
}

/** Compile (and cache) a query for a language. */
function getQuery(language: Language, source: string): Query | null {
  const key = `${language === languages.get('tsx') ? 'tsx' : 'typescript'}\n${source}`;
  const cached = queryCache.get(key);
  if (cached) return cached;
  try {
    const query = new Query(language, source);
    queryCache.set(key, query);
    return query;
  } catch {
    return null;
  }
}

/** The runner fileStructure.ts needs: compile once per language,
 *  run matches on the given node. */
function makeRunner(language: Language) {
  return (
    source: string,
    node: Node,
    options?: QueryOptions,
  ): QueryMatch[] => {
    const query = getQuery(language, source);
    if (!query) return [];
    return query.matches(node, options);
  };
}

/**
 * Parse (or incrementally re-parse) a file's text and cache the
 * tree. Fire-and-forget from the editor — returns false when the
 * file is not a TS/JS file, the engine is unavailable, or the
 * parse throws. The cached tree is what the structure readers
 * and the completion providers read, synchronously.
 */
export async function updateFileTree(
  path: string,
  content: string,
): Promise<boolean> {
  const language = getLanguageForPath(path);
  if (!language) {
    dropFileTree(path);
    return false;
  }
  if (!(await ensureTreeSitter())) return false;
  const parser = parsers.get(language);
  const lang = languages.get(language);
  if (!parser || !lang) return false;
  try {
    const existing = trees.get(path);
    let tree: Tree | null;
    if (existing && existing.language === language) {
      const edit = computeEdit(existing.text, content);
      if (edit) existing.tree.edit(edit);
      tree = parser.parse(content, existing.tree);
    } else {
      tree = parser.parse(content);
    }
    if (!tree) {
      dropFileTree(path);
      return false;
    }
    trees.set(path, { tree, text: content, language });
    return true;
  } catch {
    dropFileTree(path);
    return false;
  }
}

/** The cached tree for a file, or null (never parsed / not TS/JS /
 *  dropped). Synchronous — the providers read it on every keystroke. */
export function getFileTree(path: string): CachedTree | null {
  return trees.get(path) ?? null;
}

/** Drop a file's tree (file closed, or a non-TS/JS file). */
export function dropFileTree(path: string): void {
  const cached = trees.get(path);
  if (cached) {
    try {
      cached.tree.delete();
    } catch {
      // Already deleted — dropping is idempotent.
    }
    trees.delete(path);
  }
}

/** The structure of a cached file, or null when there is no tree. */
export function getFileStructure(path: string): FileStructure | null {
  const cached = trees.get(path);
  if (!cached) return null;
  const lang = languages.get(cached.language);
  if (!lang) return null;
  const runQuery = makeRunner(lang);
  const root = cached.tree.rootNode;
  const definitions = extractDefinitions(root, runQuery);
  return {
    path,
    language: cached.language,
    definitions,
    imports: extractImports(root, runQuery),
    exports: extractExports(root, runQuery),
    topLevelNames: definitions
      .filter((d) => isTopLevelDefinition(root, d))
      .map((d) => d.name),
    hasError: root.hasError,
  };
}

/** Top-level definition names for a file — the cheap context the
 *  composer's ghost completes from (the file being edited). */
export function getTopLevelNames(path: string): string[] {
  return getFileStructure(path)?.topLevelNames ?? [];
}

/** Identifiers the composer's ghost completes from for a file:
 *  its top-level definitions plus its imports, deduped, file
 *  order first. Empty when there is no tree. */
export function getComposerStructureIdentifiers(path: string): string[] {
  const structure = getFileStructure(path);
  if (!structure) return [];
  return [...new Set([...structure.topLevelNames, ...structure.imports])];
}

/** Drop every cached tree except the given paths (files closed). */
export function dropFileTreesExcept(openPaths: Iterable<string>): void {
  const keep = new Set(openPaths);
  for (const path of [...trees.keys()]) {
    if (!keep.has(path)) dropFileTree(path);
  }
}

/** Identifiers in scope at a Monaco position in a file — the
 *  editor provider's context. Empty when there is no tree. */
export function getIdentifiersAtPosition(
  path: string,
  lineNumber: number,
  column: number,
): string[] {
  const cached = trees.get(path);
  if (!cached) return [];
  const lang = languages.get(cached.language);
  if (!lang) return [];
  const { row, column: byteColumn } = monacoPositionToTreeSitter(
    cached.text,
    lineNumber,
    column,
  );
  try {
    return getIdentifiersInScope(
      cached.tree.rootNode,
      row,
      byteColumn,
      makeRunner(lang),
    );
  } catch {
    return [];
  }
}

/** The enclosing function at a Monaco position in a file. */
export function getEnclosingFunctionAtPosition(
  path: string,
  lineNumber: number,
  column: number,
): EnclosingFunction | null {
  const cached = trees.get(path);
  if (!cached) return null;
  const { row, column: byteColumn } = monacoPositionToTreeSitter(
    cached.text,
    lineNumber,
    column,
  );
  try {
    return getEnclosingFunction(cached.tree.rootNode, row, byteColumn);
  } catch {
    return null;
  }
}

/** Parse a standalone text (tests / tools) without touching the
 *  per-file cache. Returns null when the engine is unavailable. */
export async function parseText(
  text: string,
  language: TreeSitterLanguageId,
): Promise<Tree | null> {
  if (!(await ensureTreeSitter())) return null;
  const parser = parsers.get(language);
  if (!parser) return null;
  try {
    return parser.parse(text);
  } catch {
    return null;
  }
}

/** A runner for a standalone tree (tests / tools). */
export function makeStandaloneRunner(
  language: TreeSitterLanguageId,
): ((source: string, node: Node, options?: QueryOptions) => QueryMatch[]) | null {
  const lang = languages.get(language);
  if (!lang) return null;
  return makeRunner(lang);
}

// Re-exported for callers that only need positions.
export { positionToByteOffset };
